  FUNCTION columns_of_all(p_owner IN VARCHAR2, p_table IN VARCHAR2) RETURN t_ColumnInfo_list IS
    l_pell_ret_1 t_ColumnInfo_list;
  BEGIN
    select column_name as name, data_type, nullable, column_id, data_length
      BULK COLLECT INTO l_pell_ret_1
      FROM all_tab_columns
         where owner = upper(p_owner) and table_name = upper(p_table)
         order by column_id;
    RETURN l_pell_ret_1;
  END columns_of_all;

  FUNCTION constraints_of_all(p_owner IN VARCHAR2, p_table IN VARCHAR2) RETURN t_ConstraintInfo_list IS
    l_pell_ret_1 t_ConstraintInfo_list;
  BEGIN
    select c.constraint_name as name, c.constraint_type, cc.column_name,
               c.search_condition, c.r_constraint_name as r_constraint
      BULK COLLECT INTO l_pell_ret_1
      FROM all_constraints c
          left join all_cons_columns cc
            on cc.owner = c.owner and cc.constraint_name = c.constraint_name
         where c.owner = upper(p_owner) and c.table_name = upper(p_table)
         order by c.constraint_name, cc.position;
    RETURN l_pell_ret_1;
  END constraints_of_all;

  FUNCTION indexes_of_all(p_owner IN VARCHAR2, p_table IN VARCHAR2) RETURN t_IndexInfo_list IS
    l_pell_ret_1 t_IndexInfo_list;
  BEGIN
    select i.index_name as name, i.uniqueness, ic.column_name
      BULK COLLECT INTO l_pell_ret_1
      FROM all_indexes i
          join all_ind_columns ic
            on ic.index_owner = i.owner and ic.index_name = i.index_name
         where i.table_owner = upper(p_owner) and i.table_name = upper(p_table)
         order by i.index_name, ic.column_position;
    RETURN l_pell_ret_1;
  END indexes_of_all;

  FUNCTION foreign_keys_of_all(p_owner IN VARCHAR2, p_table IN VARCHAR2) RETURN t_ForeignKeyInfo_list IS
    l_pell_ret_1 t_ForeignKeyInfo_list;
  BEGIN
    select c.constraint_name as name, cc.column_name,
               rc.table_name as r_table, rcc.column_name as r_column_name, c.delete_rule
      BULK COLLECT INTO l_pell_ret_1
      FROM all_constraints c
          join all_cons_columns cc
            on cc.owner = c.owner and cc.constraint_name = c.constraint_name
          join all_constraints rc
            on rc.owner = c.r_owner and rc.constraint_name = c.r_constraint_name
          join all_cons_columns rcc
            on rcc.owner = rc.owner and rcc.constraint_name = rc.constraint_name
           and rcc.position = cc.position
         where c.constraint_type = 'R'
           and c.owner = upper(p_owner) and c.table_name = upper(p_table)
         order by c.constraint_name, cc.position;
    RETURN l_pell_ret_1;
  END foreign_keys_of_all;

